import sys

class N:
    __slots__ = ('v', 'nxt')
    def __init__(self, v=0, nxt=None):
        self.v = v; self.nxt = nxt

def to_list(arr):
    head = None
    for v in reversed(arr):
        head = N(v, head)
    return head

def to_arr(head):
    out = []
    while head:
        out.append(head.v); head = head.nxt
    return out

def merge_two(a, b):
    dummy = N(0)
    cur = dummy
    while a and b:
        if a.v <= b.v:
            cur.nxt = a; a = a.nxt
        else:
            cur.nxt = b; b = b.nxt
        cur = cur.nxt
    cur.nxt = a or b
    return dummy.nxt

def merge_brute(lists):
    cur = None
    for lst in lists:
        cur = merge_two(cur, lst)
    return cur

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        print(); sys.exit(0)
    k = int(data[0]); idx = 1
    lists = []
    for _ in range(k):
        size = int(data[idx]); idx += 1
        arr = list(map(int, data[idx:idx + size]))
        idx += size
        lists.append(to_list(arr))
    res = merge_brute(lists)
    print(' '.join(map(str, to_arr(res))))

