import sys
import heapq

class N:
    __slots__ = ('v', 'nxt')
    def __init__(self, v=0, nxt=None):
        self.v = v; self.nxt = nxt

def to_list(arr):
    head = None
    for v in reversed(arr):
        head = N(v, head)
    return head

def to_arr(head):
    out = []
    while head:
        out.append(head.v); head = head.nxt
    return out

def merge_best(lists):
    heap = []
    for i, lst in enumerate(lists):
        if lst:
            heapq.heappush(heap, (lst.v, i, lst))
    dummy = N(0)
    cur = dummy
    while heap:
        v, i, node = heapq.heappop(heap)
        cur.nxt = node
        cur = cur.nxt
        if node.nxt:
            heapq.heappush(heap, (node.nxt.v, i, node.nxt))
    return dummy.nxt

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        print(); sys.exit(0)
    k = int(data[0]); idx = 1
    lists = []
    for _ in range(k):
        size = int(data[idx]); idx += 1
        arr = list(map(int, data[idx:idx + size]))
        idx += size
        lists.append(to_list(arr))
    res = merge_best(lists)
    print(' '.join(map(str, to_arr(res))))
